v_add_co_u32 v[vgprLocalReadAddrMetadata+0], vcc_lo, 0xc500, v[vgprLocalReadAddrMetadata+0] //  += LdsOffsetMetadata (lower)

/* local read addresses: declare addresses b */
v_add_co_u32 v[vgprLocalReadAddrB+0], vcc_lo, 0x8100, v[vgprLocalReadAddrB+0] //  += LdsOffsetB (lower)

/******************************************/
/* Local Write Addresses                  */
/******************************************/
/* LVCA = 8 */
/* v1 = A-unroll = serial/LVCA */
s_set_vgpr_msb 12                                  // src0: 0, src1: 3, src2: 0, dst: 0
v_lshrrev_b32 v1, 3, v[vgprSerial-768]             // 1 = Serial / 8
v_and_b32 v0, 7, v[vgprSerial-768]                 // 0 = Serial % 8
/* tile *= glvw */
s_set_vgpr_msb 3072                                // src0: 0, src1: 0, src2: 0, dst: 0
v_lshlrev_b32 v0, 4, v0                            // v0 = v0 * 16
v_mov_b32 v4, v1                                   // copy for GlobalSplitU
/* LVCB = 8 */
/* v3 = B-unroll = serial%LVCB */
s_set_vgpr_msb 12                                  // src0: 0, src1: 3, src2: 0, dst: 0
v_lshrrev_b32 v2, 3, v[vgprSerial-768]             // 2 = Serial / 8
v_and_b32 v3, 7, v[vgprSerial-768]                 // 3 = Serial % 8
/* unroll *= glvw */
s_set_vgpr_msb 3072                                // src0: 0, src1: 0, src2: 0, dst: 0
v_lshlrev_b32 v3, 4, v3                            // v3 = v3 * 16
v_mov_b32 v5, v3                                   // copy for GlobalSplitU
/* LVCMetadata = 2 */
/* v7 = Metadata-unroll = serial%LVCMetadata */
s_set_vgpr_msb 12                                  // src0: 0, src1: 3, src2: 0, dst: 0
v_lshrrev_b32 v6, 1, v[vgprSerial-768]             // 6 = Serial / 2
v_and_b32 v7, 1, v[vgprSerial-768]                 // 7 = Serial % 2
/* unroll *= glvw */
s_set_vgpr_msb 3072                                // src0: 0, src1: 0, src2: 0, dst: 0
v_lshlrev_b32 v7, 4, v7                            // v7 = v7 * 16
v_mov_b32 v10, v7                                  // copy for GlobalSplitU
/* lwaUnrollAssignmentA = v4 */
/* lwaUnrollAssignmentB = v5 */
/* lwaUnrollAssignmentMetadata = v10 */

/* local write addresses: first offset a */
v_mul_u32_u24 v[vgprLocalWriteAddrA], 0x80, v4     // lwAL**(MTA + PAD)
v_add_nc_u32 v[vgprLocalWriteAddrA], v0, v[vgprLocalWriteAddrA] // lwFOA = (lwAA + lwAL*(MT0I+PAD))
                                                   //  (bpe is 1, do nothing)
v_lshrrev_b32 v8, 11, v[vgprLocalWriteAddrA]       // padding 16 per block 2048
v_lshl_add_u32 v[vgprLocalWriteAddrA], v8, 4, v[vgprLocalWriteAddrA] // padding 16 per block 2048

/* local write addresses: first offset metadata */
v_mul_u32_u24 v[vgprLocalWriteAddrMetadata], 0x24, v6 // lwMetadataL**(DepthU_Compute + PAD)
v_add_nc_u32 v[vgprLocalWriteAddrMetadata], v10, v[vgprLocalWriteAddrMetadata] // lwFOMetadata = (lwMetadataMetadata + lwMetadataL*(DepthU+PAD))
                                                   //  (bpe is 1, do nothing)
s_delay_alu instid0(VALU_DEP_1)
v_add_co_u32 v[vgprLocalWriteAddrMetadata], vcc_lo, 0xc500, v[vgprLocalWriteAddrMetadata] // lwFOMetadata = lw1J + lwL*MT1J + LDS_OFFSET_Metadata=50432

/* local write addresses: first offset b */
v_mul_u32_u24 v[vgprLocalWriteAddrB], 0x80, v2     // lwBL**(DepthU_Compute + PAD)
v_add_nc_u32 v[vgprLocalWriteAddrB], v5, v[vgprLocalWriteAddrB] // lwFOB = (lwBB + lwBL*(DepthU+PAD))
                                                   //  (bpe is 1, do nothing)
v_lshrrev_b32 v8, 8, v[vgprLocalWriteAddrB]        // padding 16 per block 256
v_lshl_add_u32 v[vgprLocalWriteAddrB], v8, 4, v[vgprLocalWriteAddrB] // padding 16 per block 256
s_delay_alu instid0(VALU_DEP_1)
v_add_co_u32 v[vgprLocalWriteAddrB], vcc_lo, 0x8100, v[vgprLocalWriteAddrB] // lwFOB = lw1J + lwL*MT1J + LDS_OFFSET_B=33024
v_mov_b32 v13, MT0                                 // set MT0 into sgpr
v_mov_b32 v12, s[sgprSizesFree+0]                  // set Free0 size
v_cvt_f32_u32 v11, v13                             // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_rcp_iflag_f32 v11, v11                           // v11 = ceil(v12 / v13)
v_cvt_f32_u32 v14, v12                             // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_mul_f32 v11, v11, v14                            // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_cvt_u32_f32 v11, v11                             // v11 = ceil(v12 / v13)
v_mul_u32_u24 v14, v11, v13                        // v11 = ceil(v12 / v13)
v_sub_nc_u32 v14, v12, v14                         // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_cmp_ne_u32 vcc_lo, v14, 0                        // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_4)
v_add_co_ci_u32 v11, vcc_lo, v11, 0, vcc_lo        // ceil
v_mov_b32 v13, MT1                                 // set MT1 into sgpr
v_mov_b32 v12, s[sgprSizesFree+1]                  // set Free1 size
v_readfirstlane_b32 s[sgprNumWorkGroups0], v11     // set back to numWorkGroup0
v_cvt_f32_u32 v11, v13                             // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_rcp_iflag_f32 v11, v11                           // v11 = ceil(v12 / v13)
v_cvt_f32_u32 v14, v12                             // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_mul_f32 v11, v11, v14                            // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_cvt_u32_f32 v11, v11                             // v11 = ceil(v12 / v13)
v_mul_u32_u24 v14, v11, v13                        // v11 = ceil(v12 / v13)
v_sub_nc_u32 v14, v12, v14                         // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_1)
v_cmp_ne_u32 vcc_lo, v14, 0                        // v11 = ceil(v12 / v13)
s_delay_alu instid0(VALU_DEP_4)
v_add_co_ci_u32 v11, vcc_lo, v11, 0, vcc_lo        // ceil
s_nop 0                                            // 1 wait states
v_readfirstlane_b32 s[sgprNumWorkGroups1], v11     // set back to numWorkGroup1
s_wait_kmcnt 0                                     // wait for -4/0 bytes of kern args

/* Early stop if N(SizeFreeJ) == 0 */
s_cmp_eq_u32 s[sgprSizeJ], 0
s_cbranch_scc0 label_NoEarlyStop_N0
label_EarlyStop_if_N_is_0:
s_endpgm
label_NoEarlyStop_N0:

/* remap wg from 1D(idxWG012) to 3D(wg2,wg1,wg0) */
/* wg2 = idxWG012 * smallMagicNumber(1/(numWG0*numWG1)) */
s_mul_i32 s16, s[sgprNumWorkGroups0], s[sgprNumWorkGroups1]
s_and_b32 s17, s[sgprGSU], 0x3fff                  // Restore GSU
s_delay_alu instid0(SALU_CYCLE_1)
s_mul_i32 s16, s16, s17
s_set_vgpr_msb 0                                   // src0: 0, src1: 0, src2: 0, dst: 0
v_cvt_f32_u32 v8, s16                              // s16 = s[sgprWorkGroup0] / s16
s_delay_alu instid0(VALU_DEP_1)
v_rcp_iflag_f32 v8, v8                             // s16 = s[sgprWorkGroup0] / s16
v_cvt_f32_u32 v9, s[sgprWorkGroup0]                // s16 = s[sgprWorkGroup0] / s16
s_delay_alu instid0(VALU_DEP_1)
v_mul_f32 v8, v8, v9                               // s16 = s[sgprWorkGroup0] / s16
s_delay_alu instid0(VALU_DEP_1)
v_cvt_u32_f32 v8, v8                               // s16 = s[sgprWorkGroup0] / s16
v_mul_u32_u24 v9, v8, s16                          // s16 = s[sgprWorkGroup0] / s16
v_sub_nc_u32 v9, s[sgprWorkGroup0], v9             // s16 = s[sgprWorkGroup0] / s16
v_cmp_eq_u32 vcc_lo, v9, s16                       // s16 = s[sgprWorkGroup0] / s16
s_mov_b32 exec_lo, vcc_lo                          // s16 = s[sgprWorkGroup0] / s16
s_delay_alu instid0(VALU_DEP_4)
v_add_nc_u32 v8, 1, v8                             // s16 = s[sgprWorkGroup0] / s16
s_mov_b32 exec_lo, -1                              // Reset exec
v_cmp_gt_u32 vcc_lo, v9, s16                       // overflow happened in remainder
s_mov_b32 exec_lo, vcc_lo                          // overflow happened in remainder
s_delay_alu instid0(VALU_DEP_2)
v_sub_nc_u32 v8, v8, 1                             // quotient - 1
s_mov_b32 exec_lo, -1                              // Reset exec
s_delay_alu instid0(VALU_DEP_1)
v_readfirstlane_b32 s16, v8                        // quotient
s_delay_alu instid0(SALU_CYCLE_1)
s_mov_b32 s[sgprWorkGroup2], s16
/* idxWG01 = idxWG012 - wg2 * numWG0 * numWG1 */
s_mul_i32 s16, s[sgprNumWorkGroups1], s[sgprNumWorkGroups0]
s_delay_alu instid0(SALU_CYCLE_1)
s_mul_i32 s16, s16, s[sgprWorkGroup2]
s_delay_alu instid0(SALU_CYCLE_1)
s_mul_i32 s16, s16, s17
s_sub_u32 s[sgprWorkGroup0], s[sgprWorkGroup0], s16
/* wg1 = idxWG01 * smallMagicNumber(1/numWG0) */
v_cvt_f32_u32 v8, s[sgprNumWorkGroups0]            // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_delay_alu instid0(VALU_DEP_1)
v_rcp_iflag_f32 v8, v8                             // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_cvt_f32_u32 v9, s[sgprWorkGroup0]                // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_delay_alu instid0(VALU_DEP_1)
v_mul_f32 v8, v8, v9                               // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_delay_alu instid0(VALU_DEP_1)
v_cvt_u32_f32 v8, v8                               // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_mul_u32_u24 v9, v8, s[sgprNumWorkGroups0]        // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_sub_nc_u32 v9, s[sgprWorkGroup0], v9             // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_cmp_eq_u32 vcc_lo, v9, s[sgprNumWorkGroups0]     // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_mov_b32 exec_lo, vcc_lo                          // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_delay_alu instid0(VALU_DEP_4)
v_add_nc_u32 v8, 1, v8                             // s16 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
s_mov_b32 exec_lo, -1                              // Reset exec
v_cmp_gt_u32 vcc_lo, v9, s[sgprNumWorkGroups0]     // overflow happened in remainder
s_mov_b32 exec_lo, vcc_lo                          // overflow happened in remainder
s_delay_alu instid0(VALU_DEP_2)
v_sub_nc_u32 v8, v8, 1                             // quotient - 1
s_mov_b32 exec_lo, -1                              // Reset exec
s_delay_alu instid0(VALU_DEP_1)
v_readfirstlane_b32 s16, v8                        // quotient
s_mov_b32 s[sgprWorkGroup1], s16
/* wg0 = idxWG01 - wg1 * numWG0 */
s_mul_i32 s16, s[sgprWorkGroup1], s[sgprNumWorkGroups0]
s_delay_alu instid0(SALU_CYCLE_1)
s_sub_u32 s[sgprWorkGroup0], s[sgprWorkGroup0], s16

/* Early stop if wg exceed */
s_cmp_ge_u32 s[sgprWorkGroup2], s[sgprSizesFree+2]
s_cbranch_scc0 label_NoEarlyStop_wgExceed
label_EarlyStop_if_wg_exceed:
s_endpgm
label_NoEarlyStop_wgExceed:

label_MultiGemmEnd:
.set sgprSrdA, 24
.set sgprSrdB, 28
.set sgprSrdMetadata, 60
.set sgprShadowLimitA, 64
.set sgprShadowLimitB, 66
.set sgprShadowLimitMetadata, 68
.set sgprStaggerUIter, 59
.set sgprWrapUA, 70
.set sgprWrapUB, 72
.set sgprWrapUMetadata, 74
.set sgprGlobalReadIncsA, 76
.set sgprGlobalReadIncsB, 77
.set sgprGlobalReadIncsMetadata, 78
s_cmp_eq_u32 s[sgprArgType], 3                     // ArgType == 3 for General Batched GEMM
s_cbranch_scc1 label_Skip_Address_Prepad_For_Pointer_Array
s_sub_u32 s[sgprAddressA+0], s[sgprAddressA+0], 16 // pre-pad to make room for possible pointer shift
s_subb_u32 s[sgprAddressA+1], s[sgprAddressA+1], 0 // pre-pad to make room for possible pointer shift
s_sub_u32 s[sgprAddressB+0], s[sgprAddressB+0], 16 // pre-pad to make room for possible pointer shift
s_subb_u32 s[sgprAddressB+1], s[sgprAddressB+1], 0 // pre-pad to make room for possible pointer shift
s_sub_u32 s[sgprAddressMetadata+0], s[sgprAddressMetadata+0], 16 // pre-pad to make room for possible pointer shift
s_subb_u32 s[sgprAddressMetadata+1], s[sgprAddressMetadata+1], 0 // pre-pad to make room for possible pointer shift
label_Skip_Address_Prepad_For_Pointer_Array:  /// Skip pre-padding of address for pointer array case

/* Short circuit condition if Alpha == 0, then sumDims=0 */
v_cmp_eq_f32 vcc_lo, s[sgprAlpha], 0.0             // s[Alpha] == 0.0f ?
s_cbranch_vccz label_AlphaNonZero                  // branch if s[Alpha] != 0
s_mov_b32 s[sgprSizesSum+0], 0                     // Set summation dim=0 if Alpha == 0
label_AlphaNonZero:
s_setreg_IMM32_b32 hwreg(26,4,1), 1                // Disable WMMA arb stall

/******************************************/
/* Begin setupNewTile                     */
/******************************************/

/* global read addresses: work-group */
/* graWorkGroup mapping */
s_and_b32 s16, s[sgprGSU], 0x3fff                  // Restore GSU
s_delay_alu instid0(SALU_CYCLE_1)
s_cmp_eq_u32 s16, 1                                // GSU == 1 ?
s_cbranch_scc1 label_GSU                           // branch if GSU == 1
// GSU-not-WGMapRR :nwg1 = (size1J + MT1J - 1) / MT1J;
s_and_b32 s16, s[sgprGSU], 0x4000                  // SCC = (GSUWGMRR == 1) ?
s_cbranch_scc1 label_GSUWGMRR                      // branch if GSUWGMRR == 1
s_and_b32 s16, s[sgprGSU], 0x3fff                  // Restore GSU
s_set_vgpr_msb 0                                   // src0: 0, src1: 0, src2: 0, dst: 0
v_cvt_f32_u32 v8, s16                              // s[sgprWorkGroup1] = s[sgprWorkGroup1] / s16
s_delay_alu instid0(VALU_DEP_1)
v_rcp_iflag_f32 v8, v8                             // s[sgprWorkGroup1] = s[sgprWorkGroup1] / s16
v_cvt_f32_u32 v9, s[sgprWorkGroup1]                // s[sgprWorkGroup1] = s[sgprWorkGroup1] / s16
s_delay_alu instid0(VALU_DEP_1)
v_mul_f32 v8, v8, v9                               // s[sgprWorkGroup1] = s[sgprWorkGroup1] / s16
s_delay_alu instid0(VALU_DEP_1)
v_cvt_u32_f32 v8, v8                               // s[sgprWorkGroup1] = s[sgprWorkGroup1] / s16
v_mul_u32_u24 v9, v8, s16                          // s[sgprWorkGroup1] = s[sgprWorkGroup1] / s16
v_sub_nc_u32 v9, s[sgprWorkGroup1], v9             // s[sgprWorkGroup1] = s[sgprWorkGroup1] / s16
v_cmp_eq_u32 vcc_lo, v9, s16                       // s[sgprWorkGroup1] = s[sgprWorkGroup1] / s16
s_mov_b32 exec_lo, vcc_lo                          // s[sgprWorkGroup1] = s[sgprWorkGroup1] / s16
s_delay_alu instid0(VALU_DEP_4)
v_add_nc_u32 v8, 1, v8                             // s[sgprWorkGroup1] = s[sgprWorkGroup1] / s16
v_mov_b32 v9, 0                                    // s[sgprGSUSumIdx] = s[sgprWorkGroup1] % s16
s_mov_b32 exec_lo, -1                              // Reset exec
v_cmp_gt_u32 vcc_lo, v9, s16                       // overflow happened in remainder
s_mov_b32 exec_lo, vcc_lo                          // overflow happened in remainder
s_delay_alu instid0(VALU_DEP_3)
v_sub_nc_u32 v8, v8, 1                             // quotient - 1
v_mul_u32_u24 v9, v8, s16                          // re-calculate remainder
v_sub_nc_u32 v9, s[sgprWorkGroup1], v9             // re-calculate remainder
s_mov_b32 exec_lo, -1                              // Reset exec
s_delay_alu instid0(VALU_DEP_3)
v_readfirstlane_b32 s[sgprWorkGroup1], v8          // quotient
s_delay_alu instid0(VALU_DEP_2)
v_readfirstlane_b32 s[sgprGSUSumIdx], v9           // remainder
s_branch label_GSUWGMRR_End
label_GSUWGMRR:
s_nop 0
s_set_vgpr_msb 0                                   // src0: 0, src1: 0, src2: 0, dst: 0
v_cvt_f32_u32 v8, s[sgprNumWorkGroups1]            // s[sgprGSUSumIdx] = s[sgprWorkGroup1] / s[sgprNumWorkGroups1]
s_delay_alu instid0(VALU_DEP_1)
v_rcp_iflag_f32 v8, v8                             // s[sgprGSUSumIdx] = s[sgprWorkGroup1] / s[sgprNumWorkGroups1]
v_cvt_f32_u32 v9, s[sgprWorkGroup1]                // s[sgprGSUSumIdx] = s[sgprWorkGroup1] / s[sgprNumWorkGroups1]
s_delay_alu instid0(VALU_DEP_1)
v_mul_f32 v8, v8, v9                               // s[sgprGSUSumIdx] = s[sgprWorkGroup1] / s[sgprNumWorkGroups1]
s_delay_alu instid0(VALU_DEP_1)
v_cvt_u32_f32 v8, v8                               // s[sgprGSUSumIdx] = s[sgprWorkGroup1] / s[sgprNumWorkGroups1]
v_mul_u32_u24 v9, v8, s[sgprNumWorkGroups1]        // s[sgprGSUSumIdx] = s[sgprWorkGroup1] / s[sgprNumWorkGroups1]
v_sub_nc_u32 v9, s[sgprWorkGroup1], v9             // s[sgprGSUSumIdx] = s[sgprWorkGroup1] / s[sgprNumWorkGroups1]
v_cmp_eq_u32 vcc_lo, v9, s[sgprNumWorkGroups1]     // s[sgprGSUSumIdx] = s[sgprWorkGroup1] / s[sgprNumWorkGroups1]
s_mov_b32 exec_lo, vcc_lo                          // s[sgprGSUSumIdx] = s[sgprWorkGroup1] / s[sgprNumWorkGroups1]
s_delay_alu instid0(VALU_DEP_4)
v_add_nc_u32 v8, 1, v8                             // s[sgprGSUSumIdx] = s[sgprWorkGroup1] / s[sgprNumWorkGroups1]
v_mov_b32 v9, 0                                    // s[sgprWorkGroup1] = s[sgprWorkGroup1] % s[sgprNumWorkGroups1]
s_mov_b32 exec_lo, -1                              // Reset exec
v_cmp_gt_u32 vcc_lo, v9, s[sgprNumWorkGroups1]     // overflow happened in remainder
s_mov_b32 exec_lo, vcc_lo                          // overflow happened in remainder
s_delay_alu instid0(VALU_DEP_3)
v_sub_nc_u32 v8, v8, 1                             // quotient - 1
v_mul_u32_u24 v9, v8, s[sgprNumWorkGroups1]        // re-calculate remainder
v_sub_nc_u32 v9, s[sgprWorkGroup1], v9             // re-calculate remainder
s_mov_b32 exec_lo, -1                              // Reset exec
s_delay_alu instid0(VALU_DEP_3)
v_readfirstlane_b32 s[sgprGSUSumIdx], v8           // quotient
s_delay_alu instid0(VALU_DEP_2)
v_readfirstlane_b32 s[sgprWorkGroup1], v9          // remainder
label_GSUWGMRR_End:
s_mov_b32 s[sgprGSULog2BpeC], 1
s_mov_b32 s[sgprGSULog2BpeD], 2
s_branch label_GSU_End
label_GSU:
s_mov_b64 s[sgprGSUSumIdx:sgprGSUSumIdx+1], 0      // Set GSUSumIdx to 0
s_mov_b32 s[sgprGSULog2BpeC], 1
s_mov_b32 s[sgprGSULog2BpeD], 1
label_GSU_End:
/* WGM Calculation */
s_mov_b32 s16, s[sgprWGM]                          // Restore WGM
s_delay_alu instid0(SALU_CYCLE_1)
s_sext_i32_i16 s16, s16                            // Restore WGM
s_delay_alu instid0(SALU_CYCLE_1)
s_cmp_gt_i32 s16, 1                                // WGM > 1 ?
s_cbranch_scc1 label_WGMPositive                   // branch if WGM > 1
s_cmp_ge_i32 s16, 0                                // WGM >= 0 ?
s_cbranch_scc1 label_WGM                           // branch if WGM >= 0
s_abs_i32 s16, s16                                 // abs(WGM)
s_set_vgpr_msb 0                                   // src0: 0, src1: 0, src2: 0, dst: 0
v_cvt_f64_u32 v[12:13], s16                        // s17 = s[sgprWorkGroup0] / s16
s_delay_alu instid0(VALU_DEP_1)
v_rcp_f64 v[12:13], v[12:13]                       // s17 = s[sgprWorkGroup0] / s16
v_cvt_f64_u32 v[14:15], s[sgprWorkGroup0]          // s17 = s[sgprWorkGroup0] / s16
s_delay_alu instid0(VALU_DEP_1)
v_mul_f64 v[12:13], v[12:13], v[14:15]             // s17 = s[sgprWorkGroup0] / s16
s_delay_alu instid0(VALU_DEP_1)
v_cvt_u32_f64 v12, v[12:13]                        // s17 = s[sgprWorkGroup0] / s16
v_mul_lo_u32 v13, v12, s16                         // s17 = s[sgprWorkGroup0] / s16
v_sub_nc_u32 v14, s[sgprWorkGroup0], v13           // s17 = s[sgprWorkGroup0] / s16
v_cmp_ge_u32 vcc_lo, v14, s16                      // s17 = s[sgprWorkGroup0] / s16
s_mov_b32 exec_lo, vcc_lo                          // s17 = s[sgprWorkGroup0] / s16
s_delay_alu instid0(VALU_DEP_4)
v_add_nc_u32 v12, v12, 1                           // s17 = s[sgprWorkGroup0] / s16
s_mov_b32 exec_lo, -1                              // Reset exec
s_delay_alu instid0(VALU_DEP_1)
v_readfirstlane_b32 s17, v12                       // quotient
s_mul_i32 s20, s17, s16                            // quotient * non-magic divisor
s_sub_u32 s20, s[sgprWorkGroup0], s20              // WorkGroup0=remainder
s_mul_i32 s20, s20, s[sgprNumWorkGroups1]          // (wg1 % WGM)*NumWorkGroups1
